def transform(grid):
    rows = len(grid)
    cols = len(grid[0])
    output = [row[:] for row in grid]

    # Find 2s row
    two_row = None
    two_positions = set()
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 2:
                two_positions.add((r, c))

    # Find all 4 sources
    sources = [(r, c) for r in range(rows) for c in range(cols) if grid[r][c] == 4]

    for sr, sc in sources:
        for dr in range(-3, 4):
            for dc in range(-3, 4):
                if abs(dr) + abs(dc) in [1, 3]:
                    nr, nc = sr + dr, sc + dc
                    if 0 <= nr < rows and 0 <= nc < cols:
                        if sr == nr and sc == nc:
                            output[sr][sc] = 0
                        elif (nr, nc) not in two_positions:
                            output[nr][nc] = 4

    return output

